// The condition keys of the aws connect service.
const (
	ConditionKeyAssignmentType                                   = "connect:AssignmentType"
	ConditionKeyAttributeType                                    = "connect:AttributeType"
	ConditionKeyChannel                                          = "connect:Channel"
	ConditionKeyContactAssociationId                             = "connect:ContactAssociationId"
	ConditionKeyContactInitiationMethod                          = "connect:ContactInitiationMethod"
	ConditionKeyExpressionValue                                  = "connect:ExpressionValue"
	ConditionKeyFlowType                                         = "connect:FlowType"
	ConditionKeyInstanceId                                       = "connect:InstanceId"
	ConditionKeyListRealtimeContactAnalysisSegmentsByOutputType  = "connect:ListRealtimeContactAnalysisSegmentsByOutputType"
	ConditionKeyListRealtimeContactAnalysisSegmentsBySegmentType = "connect:ListRealtimeContactAnalysisSegmentsBySegmentType"
	ConditionKeyMonitorCapabilities                              = "connect:MonitorCapabilities"
	ConditionKeyPreferredUserArn                                 = "connect:PreferredUserArn"
	ConditionKeySearchContactsByContactAnalysis                  = "connect:SearchContactsByContactAnalysis"
	ConditionKeyStorageResourceType                              = "connect:StorageResourceType"
	ConditionKeySubtype                                          = "connect:Subtype"
	ConditionKeyUserArn                                          = "connect:UserArn"
)

// The condition keys that take a value. They return a plain string, so wrap
// them in policy.Key when a condition wants a policy.ConditionKey.
func ConditionKeyPrimaryAttributeFor(value string) string { return "connect:PrimaryAttribute/" + value }

func ConditionKeySearchTagFor(value string) string { return "connect:SearchTag/" + value }
